"""Shipping price for one parcel: base rate times band multiplier, plus the
band's remote surcharge when the zone is remote. All pricing data is in the CSVs."""
import csv
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

HERE = Path(__file__).parent


def _flag(value):
    if value not in ("0", "1"):
        raise ValueError("remote must be 0 or 1, got %r" % value)
    return value == "1"


def _load():
    with (HERE / "zone_rates.csv").open() as f:
        zones = {r["zone"]: (Decimal(r["base_rate"]), _flag(r["remote"]))
                 for r in csv.DictReader(f)}
    with (HERE / "weight_bands.csv").open() as f:
        bands = [(float(r["min_kg"]), float(r["max_kg"]), Decimal(r["multiplier"]),
                  Decimal(r["remote_surcharge"])) for r in csv.DictReader(f)]
    return zones, bands


ZONES, BANDS = _load()


def price(zone, weight_kg):
    for lo, hi, multiplier, surcharge in BANDS:
        if lo <= weight_kg < hi:
            break
    else:
        raise ValueError("no band for %.1f kg" % weight_kg)
    base, remote = ZONES[zone]
    raw = base * multiplier + (surcharge if remote else Decimal("0"))
    return raw.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

