"""Shipping price for one parcel, all rules read from pricing.json."""
import json
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

CONFIG = json.loads((Path(__file__).parent / "pricing.json").read_text())
ZONES = {z: (Decimal(v["base_rate"]), v["remote"]) for z, v in CONFIG["zones"].items()}
BANDS = [(b["min_kg"], b["max_kg"], Decimal(b["multiplier"]), b["heavy"]) for b in CONFIG["bands"]]
SURCHARGE = Decimal(CONFIG["remote_heavy_surcharge"])


def price(zone, weight_kg):
    base, remote = ZONES[zone]
    for lo, hi, multiplier, heavy in BANDS:
        if lo <= weight_kg < hi:
            break
    else:
        raise ValueError("no band for %.1f kg" % weight_kg)
    raw = base * multiplier
    if remote and heavy:
        raw += SURCHARGE
    return raw.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

