import csv
import importlib.util
import sys
from collections import Counter
from pathlib import Path

project = Path(sys.argv[1])
proposed = Path(sys.argv[2])


def rows(path):
    with path.open(newline="") as f:
        return list(csv.DictReader(f))


spec = importlib.util.spec_from_file_location("old_route", project / "route.py")
old = importlib.util.module_from_spec(spec)
spec.loader.exec_module(old)

owners = {r["service"]: r for r in rows(proposed / "service_owners.csv")}
sevs = {r["severity"]: r for r in rows(proposed / "severity_channels.csv")}


def new_route(service, severity):
    o = owners[service]
    s = sevs[severity]
    if s["urgent"] == "yes" and o["urgent_team"]:
        return o["urgent_team"], o["urgent_channel"]
    return o["team"], s["channel"]


def try_route(fn, service, severity):
    try:
        return fn(service, severity)
    except KeyError as e:
        return f"KeyError({e})"


alerts = rows(project / "alerts_2026-09.csv")
print("alerts:", len(alerts))
print("services:", sorted(Counter(a["service"] for a in alerts).items()))
print("severities:", sorted(Counter(a["severity"] for a in alerts).items()))

override_hits = [
    a for a in alerts
    if a["service"] in old.FINANCE_SERVICES and a["severity"] in old.URGENT
]
print("override hits (payments/ledger, sev1/sev2):", len(override_hits))

mismatches = []
old_dest = Counter()
for a in alerts:
    s, sev = a["service"], a["severity"]
    o = try_route(old.route, s, sev)
    n = try_route(new_route, s, sev)
    old_dest[o] += 1
    if o != n:
        mismatches.append((a["alert_id"], s, sev, o, n))

print("old destinations:")
for dest, count in old_dest.most_common():
    print(" ", count, dest)
print("mismatches:", len(mismatches))
for m in mismatches[:20]:
    print(" ", m)

