import csv, sys, importlib.util
from collections import Counter
from decimal import Decimal, ROUND_HALF_UP

src = sys.argv[1]
spec = importlib.util.spec_from_file_location("price", src + "/price.py")
p = importlib.util.module_from_spec(spec); spec.loader.exec_module(p)

# Proposed single rate card: band boundaries + final price per zone, surcharge baked in.
bands = [(b, lo, hi) for b, lo, hi, _ in p.BANDS]
card = {}
for b, lo, hi in bands:
    for z in p.ZONES:
        card[(z, b)] = p.price(z, (lo + hi) / 2 if False else lo)  # price at band floor
def new_price(zone, w):
    for b, lo, hi in bands:
        if lo <= w < hi:
            return card[(zone, b)]
    raise ValueError("no band for %.1f kg" % w)

rows = list(csv.DictReader(open(src + "/orders_2026-09.csv")))
print("orders:", len(rows), "unique ids:", len({r["order_id"] for r in rows}))
print("zones:", sorted(Counter(r["zone"] for r in rows).items()))
ws = [float(r["weight_kg"]) for r in rows]
print("weight min/max:", min(ws), max(ws))
bandcount = Counter(p.band_for(float(r["weight_kg"])) for r in rows)
print("bands:", sorted(bandcount.items()))

diff = errs = 0
surch = 0
for r in rows:
    z, w = r["zone"], float(r["weight_kg"])
    try:
        old = p.price(z, w)
    except Exception as e:
        errs += 1; print("old error", r, e); continue
    new = new_price(z, w)
    if old != new:
        diff += 1; print("DIFF", r, old, new)
    if z in p.REMOTE_ZONES and p.band_for(w) in p.HEAVY_BANDS:
        surch += 1
print("differences:", diff, "errors:", errs, "orders hit by remote surcharge:", surch)

# grid-cell rounding check: any cell that sits on a half-cent before rounding?
half = 0
for z, base in p.ZONES.items():
    for b, _, _, m in p.BANDS:
        raw = base * m + (p.REMOTE_HEAVY_SURCHARGE if z in p.REMOTE_ZONES and b in p.HEAVY_BANDS else 0)
        if raw != raw.quantize(Decimal("0.01")):
            half += 1
            if (raw * 1000) % 10 == 5: print("half-cent cell", z, b, raw)
print("cells needing rounding:", half, "of", len(p.ZONES) * len(p.BANDS))

print("band," + ",".join(p.ZONES))
for b, lo, hi in bands:
    print(f"{b},{lo:g},{hi:g}," + ",".join(str(card[(z, b)]) for z in p.ZONES))
